227		}
228		if c.CurrentVersion == nil || c.CurrentVersion.ID != ov2.ID || c.CurrentVersion.Number != 2 ||
229			c.CurrentVersion.Content != "医嘱第 2 版内容" {
230			t.Fatalf("current version wrong: %+v", c.CurrentVersion)
231		}
232		if want := []ID{ov1.ID, ov2.ID}; !reflect.DeepEqual(c.Record.Versions, want) {
233			t.Fatalf("version id list = %v, want %v", c.Record.Versions, want)
234		}
235		if len(c.Versions) != 2 {
236			t.Fatalf("full history should keep 2 versions, got %d", len(c.Versions))
237		}
238		if c.Versions[0].Number != 1 || c.Versions[0].Content != "医嘱第 1 版内容" ||
239			c.Versions[0].PrevID != "" || c.Versions[0].Reason != "" {
